parameters.jsCode:
const cfg = $('Config').first().json;
const raw = $json.content[0].text;
const start = raw.indexOf('[');
const end = raw.lastIndexOf(']');
if (start < 0 || end < 0) throw new Error('Claude did not return a JSON array');
const posts = JSON.parse(raw.slice(start, end + 1));
return posts.slice(0, cfg.postsPerRun).map((p, i) => ({ json: {
  title: String(p.title || 'Draft ' + (i + 1)).slice(0, 120),
  text: String(p.text || '').slice(0, 2000),
  key: 'bb-' + cfg.today + '-' + i,
  workspaceId: cfg.workspaceId,
  accountIds: cfg.accountIds,
  openpostUrl: cfg.openpostUrl
}}));
